import {useEffect,useMemo,useState} from 'react';
import {CalendarDays,Check,ChevronLeft,ChevronRight,Clock,Download,LayoutDashboard,LogOut,Mail,Menu,Plus,Search,ShieldCheck,Ticket,Users,BookOpen,UserRound,Settings,Trash2,Edit3,X} from 'lucide-react';
import {motion,AnimatePresence} from 'framer-motion';
import ExcelJS from 'exceljs';
import {supabase,supabaseConfigured} from './lib/supabase';
import * as api from './lib/api';
import type {Booking,BookingStatus,Course,Instructor,Mode,Slot,Student,Schedule} from './types';

const brand={navy:'#102A4A',orange:'#F47B20'};
const seedCourses=['AI Development','Web Development','Amazon','Shopify','Graphic Designing','UI/UX Designing','Cloud Computing','IELTS','PTE','Digital Marketing'];
const steps=['Student','Course','Instructor','Mode','Date','Time','Confirm','Ticket'];
const path=()=>window.location.pathname;

function Header(){return <header style={{background:'#fff',borderBottom:'1px solid #E5E7EB',position:'sticky',top:0,zIndex:20}}><div className="container" style={{height:76,display:'flex',alignItems:'center',justifyContent:'space-between'}}><Link to="/" style={{display:'flex',alignItems:'center'}}><img src="/assets/aztec-logo.png" alt="AZTEC IT INSTITUTE" style={{width:205,height:70,objectFit:'contain'}}/></Link><a href="/admin/login" className="btn btn-ghost" style={{textDecoration:'none'}}>Admin</a></div></header>}
function Link({to,children,...rest}:{to:string;children:React.ReactNode;[k:string]:any}){return <a href={to} {...rest}>{children}</a>}
function Stepper({current}:{current:number}){return <div style={{display:'flex',gap:6,overflowX:'auto',padding:'6px 0 20px'}}>{steps.map((s,i)=><div key={s} style={{display:'flex',alignItems:'center',gap:6,minWidth:'fit-content'}}><div style={{width:28,height:28,borderRadius:99,display:'grid',placeItems:'center',background:i<current?brand.navy:i===current?brand.orange:'#E5E7EB',color:i<=current?'#fff':'#6B7280',fontSize:12,fontWeight:800}}>{i<current?<Check size={15}/>:i+1}</div><span style={{fontSize:12,fontWeight:700,color:i===current?brand.navy:'#6B7280'}}>{s}</span>{i<steps.length-1&&<ChevronRight size={14} className="muted"/>}</div>)}</div>}
function Home(){return <><Header/><main><section style={{background:'linear-gradient(135deg,#102A4A 0%,#173d67 60%,#102A4A 100%)',color:'#fff',padding:'72px 0'}}><div className="container" style={{display:'grid',gridTemplateColumns:'1.3fr .7fr',gap:40,alignItems:'center'}}><div><div style={{display:'inline-flex',gap:8,alignItems:'center',padding:'8px 12px',border:'1px solid rgba(255,255,255,.18)',borderRadius:99,fontSize:13}}><ShieldCheck size={16}/> Official Demo Booking Portal</div><h1 style={{fontSize:'clamp(40px,6vw,68px)',lineHeight:1.02,margin:'20px 0 18px',letterSpacing:-2}}>Book Your Free<br/><span style={{color:brand.orange}}>Demo Class</span></h1><p style={{fontSize:18,lineHeight:1.7,color:'rgba(255,255,255,.78)',maxWidth:650}}>Choose your course, instructor, preferred date and available time — all in one simple process.</p><a href="/book" className="btn btn-orange" style={{display:'inline-flex',alignItems:'center',gap:8,textDecoration:'none',marginTop:18}}>Book a Demo <ChevronRight size={18}/></a></div><div className="card" style={{padding:22,background:'#fff',color:brand.navy}}><img src="/assets/aztec-logo.png" alt="Aztec" style={{width:'100%',height:110,objectFit:'contain'}}/><div style={{borderTop:'1px solid #E5E7EB',paddingTop:18,display:'grid',gap:12}}>{['Search or register with phone','Choose course & instructor','Pick an available slot','Get your demo ticket'].map((x,i)=><div key={x} style={{display:'flex',gap:12,alignItems:'center'}}><div style={{width:30,height:30,borderRadius:9,background:'#F5F7FA',display:'grid',placeItems:'center',color:brand.orange,fontWeight:800}}>{i+1}</div><span style={{fontWeight:600,fontSize:14}}>{x}</span></div>)}</div></div></div></section><section className="container" style={{padding:'55px 0'}}><h2 style={{fontSize:32,marginBottom:8}}>How it works</h2><p className="muted">Simple for students. Fully manageable for your admin team.</p><div className="grid" style={{gridTemplateColumns:'repeat(4,1fr)',marginTop:24}}>{['Search / Register','Choose Course','Instructor & Time','Get Ticket'].map((x,i)=><div className="card" key={x} style={{padding:22}}><div style={{color:brand.orange,fontWeight:800,fontSize:13}}>0{i+1}</div><h3>{x}</h3><p className="muted" style={{lineHeight:1.6,fontSize:14}}>{['Find your record by phone or register once.','Select from active institute courses.','Choose mode, date and an available slot.','Receive a branded confirmation ticket.'][i]}</p></div>)}</div></section></main></>}

function BookingFlow(){const [step,setStep]=useState(0);const [phone,setPhone]=useState('');const [student,setStudent]=useState<Student|null>(null);const [newName,setNewName]=useState('');const [courses,setCourses]=useState<Course[]>([]);const [course,setCourse]=useState<Course|null>(null);const [instructors,setInstructors]=useState<Instructor[]>([]);const [instructor,setInstructor]=useState<Instructor|null>(null);const [mode,setMode]=useState<Mode>('Online');const [date,setDate]=useState('');const [slots,setSlots]=useState<Slot[]>([]);const [slot,setSlot]=useState<Slot|null>(null);const [booking,setBooking]=useState<Booking|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
useEffect(()=>{api.getCourses().then(setCourses).catch(e=>setError(e.message))},[]);
const dates=useMemo(()=>{const out:string[]=[];const d=new Date();d.setHours(0,0,0,0);for(let i=0;i<30;i++){const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,'0');const day=String(d.getDate()).padStart(2,'0');out.push(`${y}-${m}-${day}`);d.setDate(d.getDate()+1)}return out},[]);
async function lookup(){setError('');setBusy(true);try{const s=await api.findStudent(phone);setStudent(s);if(!s)setStep(1);else setStep(1)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
async function register(){setBusy(true);setError('');try{const s=await api.registerStudent(newName,phone);setStudent(s);setStep(1)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
async function chooseCourse(c:Course){setCourse(c);setBusy(true);setError('');try{setInstructors(await api.getInstructors(c.id));setStep(2)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
async function chooseInstructor(i:Instructor){setInstructor(i);setStep(3)}
async function chooseMode(m:Mode){setMode(m);setStep(4)}
async function chooseDate(d:string){setDate(d);setSlot(null);setBusy(true);setError('');try{const nextSlots=await api.getSlots(instructor!.id,course!.id,mode,d);setSlots(nextSlots);setStep(5)}catch(e:any){setSlots([]);setError(e.message)}finally{setBusy(false)}}
async function confirm(){
 if(!student||!course||!instructor||!date||!slot){setError('Please complete all booking selections before confirming.');return}
 setBusy(true);setError('');
 try{
  const b=await api.createBooking({studentId:student.id,courseId:course.id,instructorId:instructor.id,mode,date,start:slot.start});
  setBooking(b);
  setStep(7);
  if(window.location.hostname==='localhost'||window.location.hostname==='127.0.0.1'){
   try{
    await api.sendBookingNotification(b.booking_code);
   }catch(mailError:any){
    setError(`Booking confirmed (${b.booking_code}), but instructor email could not be sent locally. ${mailError?.message||''}`.trim());
   }
  }
 }catch(e:any){
  const message=String(e?.message||e);
  if(message.includes('BOOKED')||message.toLowerCase().includes('duplicate')) setError('That slot was just booked by someone else. Please choose another time.');
  else if(message.includes('SLOT_UNAVAILABLE')) setError('This time slot is no longer available. Please choose another time.');
  else if(message.includes('SLOT_BLOCKED')) setError('This time slot has been blocked. Please choose another time.');
  else setError(`Booking could not be created: ${message}`);
 }finally{setBusy(false)}
}
function back(){if(step>0)setStep(step-1)}
return <><Header/><main className="container" style={{padding:'35px 0 70px'}}><Stepper current={step}/><div className="card fade" style={{padding:'clamp(20px,5vw,42px)',maxWidth:820,margin:'auto'}}>{error&&<div style={{background:'#fff1ed',border:'1px solid #ffd3c8',color:'#b33a1f',padding:13,borderRadius:12,marginBottom:18}}>{error}</div>}{step===0&&<div><h1>Find your student record</h1><p className="muted">Enter your Pakistani mobile number to continue.</p><label className="label">Phone Number</label><input className="field" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="03001234567" inputMode="tel"/><button className="btn btn-primary" style={{marginTop:16}} disabled={busy||phone.length<10} onClick={lookup}>{busy?'Checking…':'Continue'}</button></div>}{step===1&&<div>{student?<><h1>Welcome back, {student.name}</h1><p className="muted">Student ID: <b>{student.student_code}</b>. Choose a course for your demo.</p></>:<><h1>Register as a new student</h1><p className="muted">We found no active record for {phone}. Register once and continue.</p><label className="label">Full Name</label><input className="field" value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Your full name"/><button className="btn btn-primary" style={{marginTop:16}} disabled={busy||newName.trim().length<2} onClick={register}>{busy?'Registering…':'Register & Continue'}</button></>}<div style={{marginTop:30}}><h3>Select Course</h3><div className="grid" style={{gridTemplateColumns:'repeat(2,1fr)'}}>{courses.map(c=><button key={c.id} className="btn btn-ghost" style={{textAlign:'left',padding:16}} onClick={()=>chooseCourse(c)}>{c.name}<span className="muted" style={{display:'block',fontSize:11,marginTop:4}}>{c.course_code}</span></button>)}</div></div></div>}{step===2&&<div><h1>Select Instructor</h1><p className="muted">Available instructors for <b>{course?.name}</b>.</p>{instructors.length?<div className="grid">{instructors.map(i=><button key={i.id} className="btn btn-ghost" style={{textAlign:'left',padding:18}} onClick={()=>chooseInstructor(i)}><div style={{fontWeight:800}}>{i.name}</div><div className="muted" style={{fontSize:13}}>{i.email}</div></button>)}</div>:<p className="muted">No active instructor is assigned to this course yet.</p>}</div>}{step===3&&<div><h1>Choose Demo Mode</h1><p className="muted">Select how you want to attend.</p><div className="grid" style={{gridTemplateColumns:'1fr 1fr'}}>{(['Online','Physical'] as Mode[]).map(m=><button key={m} className="btn btn-ghost" style={{padding:25,border:m===mode?'2px solid '+brand.orange:'1px solid #E5E7EB'}} onClick={()=>chooseMode(m)}><div style={{fontSize:18,fontWeight:800}}>{m}</div><div className="muted" style={{fontSize:13,marginTop:5}}>{m==='Online'?'Attend remotely':'Attend at institute'}</div></button>)}</div></div>}{step===4&&<div><h1>Select Date</h1><p className="muted">Past dates and unavailable dates are disabled by the schedule.</p><div className="grid" style={{gridTemplateColumns:'repeat(3,1fr)'}}>{dates.map(d=><button key={d} className="btn btn-ghost" onClick={()=>chooseDate(d)}>{new Date(d+'T00:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</button>)}</div></div>}{step===5&&<div><h1>Select Time</h1><p className="muted">{new Date(date+'T00:00:00').toLocaleDateString()} · {mode} · {instructor?.name}</p><div className="grid" style={{gridTemplateColumns:'repeat(3,1fr)'}}>{slots.map(s=>{const available=s.available===true;return <button key={s.start} type="button" disabled={!available||busy} className="btn btn-ghost" style={{opacity:available?1:.45,cursor:available?'pointer':'not-allowed'}} onClick={()=>{if(!available)return;setError('');setSlot({...s,end:s.end??s.end_time});setStep(6)}}><Clock size={15} style={{verticalAlign:'-2px',marginRight:5}}/>{s.start.slice(0,5)}{!available&&<span style={{display:'block',fontSize:11,marginTop:3,color:'#b33a1f'}}>Booked</span>}</button>})}</div>{!slots.length&&<p className="muted">No schedule or available slots for this date. Please choose another date.</p>}{slots.some(s=>s.available)&&<p className="muted" style={{marginTop:12}}>Select an available time to continue to confirmation.</p>}</div>}{step===6&&<div><h1>Confirm Demo</h1><div style={{display:'grid',gap:10,margin:'22px 0'}}>{[['Student',student?.name],['Phone',student?.phone],['Course',course?.name],['Instructor',instructor?.name],['Mode',mode],['Date',date],['Time',slot?.start?.slice(0,5)+' – '+(slot?.end??slot?.end_time)?.slice(0,5)]].map(([a,b])=><div key={a} style={{display:'flex',justifyContent:'space-between',gap:15,borderBottom:'1px solid #F0F1F3',padding:'10px 0'}}><span className="muted">{a}</span><b style={{textAlign:'right'}}>{b}</b></div>)}</div><button className="btn btn-orange" disabled={busy} onClick={confirm}>{busy?'Confirming…':'Confirm Demo Class'}</button></div>}{step===7&&booking&&<TicketView booking={booking}/>}<div style={{marginTop:28,display:'flex',justifyContent:'space-between'}}>{step>0&&step<7?<button className="btn btn-ghost" onClick={back}><ChevronLeft size={16}/> Back</button>:<span/>}{step===7&&<a href="/book" className="btn btn-primary" style={{textDecoration:'none'}}>Book Another Demo</a>}</div></div></main></>}
function TicketView({booking}:{booking:Booking}){return <div><div style={{textAlign:'center'}}><div style={{display:'inline-flex',padding:10,borderRadius:99,background:'#ecfdf3',color:'#15803d'}}><Check/></div><h1>Demo Class Confirmed</h1><p className="muted">Your booking has been saved successfully.</p></div><div style={{marginTop:25,border:'2px dashed #d7dce3',borderRadius:18,padding:24,background:'linear-gradient(#fff,#fbfcfe)'}}><img src="/assets/aztec-logo.png" alt="AZTEC" style={{width:220,height:72,objectFit:'contain',display:'block',margin:'0 auto 12px'}}/><div style={{textAlign:'center',fontWeight:800,color:brand.orange,letterSpacing:1}}>DEMO CLASS CONFIRMED</div><div style={{fontSize:22,fontWeight:800,textAlign:'center',margin:'10px 0 22px'}}>{booking.booking_code}</div><div className="grid" style={{gridTemplateColumns:'1fr 1fr'}}>{[['Student ID',booking.student_code],['Student',booking.student_name],['Phone',booking.student_phone],['Course',booking.course_name],['Instructor',booking.instructor_name],['Mode',booking.mode],['Date',booking.demo_date],['Time',booking.start_time.slice(0,5)+' – '+booking.end_time.slice(0,5)],['Status',booking.status],['Created',new Date(booking.created_at).toLocaleString()]].map(([a,b])=><div key={a} style={{padding:10,background:'#F5F7FA',borderRadius:10}}><div className="muted" style={{fontSize:11}}>{a}</div><b style={{fontSize:13}}>{b}</b></div>)}</div></div><div style={{display:'flex',gap:10,justifyContent:'center',marginTop:18}}><button className="btn btn-primary" onClick={()=>window.print()}><Download size={16}/> Print / Save PDF</button></div></div>}

function AdminLogin(){
 const [username,setUsername]=useState('Admin');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);
 async function login(e:any){e.preventDefault();setBusy(true);setError('');if(!supabase){setError('Supabase is not configured. Complete .env setup first.');setBusy(false);return}try{const email=username.trim().toLowerCase()==='admin'?'admin@aztec.local':username.trim();const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;window.location.href='/admin'}catch(e:any){setError(e?.message||'Invalid admin credentials or auth setup.')}finally{setBusy(false)}}
 return <main style={{minHeight:'100vh',display:'grid',placeItems:'center',padding:20}}><form onSubmit={login} className="card" style={{width:'min(430px,100%)',padding:32}}><img src="/assets/aztec-logo.png" alt="AZTEC" style={{width:'100%',height:110,objectFit:'contain'}}/><h1>Admin Login</h1><p className="muted">Secure management portal.</p>{error&&<div style={{background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10,margin:'12px 0'}}>{error}</div>}<label className="label">Username</label><input className="field" value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username"/><label className="label" style={{marginTop:14}}>Password</label><input className="field" type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/><button className="btn btn-primary" style={{width:'100%',marginTop:18}} disabled={busy}>{busy?'Signing in…':'Sign In'}</button><p className="muted" style={{fontSize:12,marginTop:16}}>Use <b>Admin</b> for the username. It maps to the configured admin account.</p></form></main>}

function Admin(){
 const [authed,setAuthed]=useState(false);const [tab,setTab]=useState('Dashboard');const [open,setOpen]=useState(false);const [courses,setCourses]=useState<Course[]>([]);const [instructors,setInstructors]=useState<Instructor[]>([]);const [students,setStudents]=useState<Student[]>([]);const [bookings,setBookings]=useState<Booking[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');
 useEffect(()=>{if(!supabase){setLoading(false);return}supabase.auth.getSession().then(({data})=>{if(!data.session)window.location.href='/admin/login';else{setAuthed(true);load()}})},[]);
 async function load(){setLoading(true);setError('');try{const [c,i,s,b]=await Promise.all([supabase!.from('courses').select('*').order('name'),supabase!.from('instructors').select('*').order('name'),supabase!.from('students').select('*').order('created_at',{ascending:false}).limit(500),supabase!.from('demo_bookings').select('*').order('created_at',{ascending:false}).limit(500)]);for(const x of [c,i,s,b])if(x.error)throw x.error;setCourses(c.data||[]);setInstructors(i.data||[]);setStudents(s.data||[]);setBookings(b.data||[])}catch(e:any){setError(e.message)}finally{setLoading(false)}}
 async function logout(){await supabase?.auth.signOut();window.location.href='/admin/login'}
 if(!authed&&supabaseConfigured)return null;
 const counts={students:students.length,bookings:bookings.length,today:bookings.filter(b=>b.demo_date===new Date().toISOString().slice(0,10)&&b.status==='Confirmed').length,upcoming:bookings.filter(b=>b.demo_date>=new Date().toISOString().slice(0,10)&&b.status==='Confirmed').length,completed:bookings.filter(b=>b.status==='Completed').length,cancelled:bookings.filter(b=>b.status==='Cancelled').length};
 const nav=[['Dashboard',LayoutDashboard],['Students',Users],['Courses',BookOpen],['Instructors',UserRound],['Schedules',CalendarDays],['Demo Bookings',Ticket],['Reports / Exports',Download],['Settings',Settings]] as any[];
 return <div style={{minHeight:'100vh',background:'#F5F7FA',display:'flex'}}><aside style={{width:250,background:brand.navy,color:'#fff',padding:18,position:'fixed',height:'100vh',zIndex:30,overflowY:'auto'}}><img src="/assets/aztec-logo.png" alt="AZTEC" style={{width:'100%',height:85,objectFit:'contain',background:'#fff',borderRadius:12}}/><div style={{marginTop:24,display:'grid',gap:6}}>{nav.map(([n,I])=><button key={n} onClick={()=>{setTab(n);setOpen(false)}} style={{display:'flex',alignItems:'center',gap:11,padding:'12px 13px',border:0,borderRadius:10,background:tab===n?'rgba(255,255,255,.12)':'transparent',color:'#fff',textAlign:'left'}}><I size={17}/>{n}</button>)}</div><button onClick={logout} style={{position:'absolute',bottom:22,left:18,right:18,padding:12,border:0,borderRadius:10,background:'rgba(255,255,255,.1)',color:'#fff',display:'flex',gap:10,alignItems:'center'}}><LogOut size={17}/> Logout</button></aside><section style={{marginLeft:250,width:'calc(100% - 250px)',minHeight:'100vh'}}><div style={{background:'#fff',borderBottom:'1px solid #E5E7EB',height:72,display:'flex',alignItems:'center',justifyContent:'space-between',padding:'0 28px',position:'sticky',top:0,zIndex:20}}><div><b style={{fontSize:20}}>{tab}</b><div className="muted" style={{fontSize:12}}>AZTEC IT INSTITUTE</div></div><div style={{display:'flex',alignItems:'center',gap:10}}><Mail size={18} className="muted"/><span className="muted" style={{fontSize:13}}>Admin</span></div></div><div className="container" style={{padding:'28px 0'}}>{error&&<div style={{background:'#fff1ed',padding:12,borderRadius:10,color:'#b33a1f',marginBottom:18}}>{error}</div>}{loading?<div className="card" style={{padding:30}}>Loading admin data…</div>:tab==='Dashboard'?<Dashboard counts={counts} bookings={bookings} courses={courses} instructors={instructors}/>:tab==='Students'?<StudentAdmin students={students} bookings={bookings} reload={load}/>:tab==='Courses'?<CourseAdmin courses={courses} bookings={bookings} reload={load}/>:tab==='Instructors'?<InstructorAdmin instructors={instructors} courses={courses} bookings={bookings} reload={load}/>:tab==='Schedules'?<ScheduleAdmin instructors={instructors} courses={courses}/>:tab==='Demo Bookings'?<BookingAdmin bookings={bookings} courses={courses} instructors={instructors} students={students} reload={load}/>:tab==='Reports / Exports'?<Reports students={students} courses={courses} instructors={instructors} bookings={bookings}/>:<div className="card" style={{padding:28}}><h2>{tab}</h2><p className="muted">Use the Schedules module to create, edit and delete instructor timings.</p></div>}</div></section></div>}

function Dashboard({counts,bookings,courses,instructors}:{counts:any;bookings:Booking[];courses:Course[];instructors:Instructor[]}){return <div><div className="grid" style={{gridTemplateColumns:'repeat(4,1fr)'}}>{[['Students',counts.students,Users],['Demo Bookings',counts.bookings,Ticket],['Today',counts.today,CalendarDays],['Upcoming',counts.upcoming,Clock],['Completed',counts.completed,Check],['Cancelled',counts.cancelled,X],['Active Courses',courses.filter(c=>c.active).length,BookOpen],['Active Instructors',instructors.filter(i=>i.active).length,UserRound]].map(([a,b,I]:any)=><div className="card" key={a} style={{padding:20}}><I size={18} color={brand.orange}/><div className="muted" style={{fontSize:12,marginTop:12}}>{a}</div><div style={{fontSize:28,fontWeight:800,marginTop:3}}>{b}</div></div>)}</div><div className="card" style={{padding:22,marginTop:20}}><h3>Recent bookings</h3>{bookings.slice(0,8).map(b=><div key={b.id} style={{display:'grid',gridTemplateColumns:'1.3fr 1fr 1fr 1fr',gap:12,padding:'13px 0',borderBottom:'1px solid #F0F1F3',fontSize:13}}><b>{b.booking_code}</b><span>{b.student_name}</span><span>{b.course_name}</span><span>{b.demo_date} · {b.start_time.slice(0,5)}</span></div>)}</div></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <div><label className="label">{label}</label>{children}</div>}

function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){return <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,.38)',display:'grid',placeItems:'center',padding:20,zIndex:100}}><div className="card" style={{width:`min(${wide?'820px':'620px'},100%)`,padding:26,maxHeight:'90vh',overflowY:'auto'}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:15}}><h2 style={{margin:0}}>{title}</h2><button className="btn btn-ghost" onClick={onClose} aria-label="Close"><X size={18}/></button></div>{children}</div></div>}

function ActionButtons({onEdit,onDelete}:{onEdit:()=>void;onDelete:()=>void}){return <div style={{display:'flex',gap:6,flexWrap:'wrap'}}><button className="btn btn-ghost" style={{padding:'7px 10px'}} onClick={onEdit}><Edit3 size={14}/> Edit</button><button className="btn btn-ghost" style={{padding:'7px 10px',color:'#b33a1f'}} onClick={onDelete}><Trash2 size={14}/> Delete</button></div>}

function StudentAdmin({students,bookings,reload}:{students:Student[];bookings:Booking[];reload:()=>void}){
 const [q,setQ]=useState(''); const [editing,setEditing]=useState<Student|null>(null); const [name,setName]=useState(''); const [phone,setPhone]=useState(''); const [active,setActive]=useState(true); const [busy,setBusy]=useState(false); const [msg,setMsg]=useState('');
 const filtered=students.filter(s=>`${s.student_code} ${s.name} ${s.phone}`.toLowerCase().includes(q.toLowerCase()));
 function openEdit(s:Student){setEditing(s);setName(s.name);setPhone(s.phone);setActive(s.active);setMsg('')}
 async function save(){if(!supabase||!editing)return;setBusy(true);setMsg('');try{const normalized=api.normalizePhone(phone);const {error}=await supabase.from('students').update({name:name.trim(),phone:normalized,active}).eq('id',editing.id);if(error)throw error;setEditing(null);await reload()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 async function remove(s:Student){if(!supabase)return;const has=bookings.some(b=>b.student_id===s.id);if(has){setMsg(`Cannot permanently delete ${s.name} because booking history exists. Deactivate the student instead.`);return}if(!confirm(`Delete student ${s.name} (${s.student_code})?`))return;const {error}=await supabase.from('students').delete().eq('id',s.id);if(error)setMsg(error.message);else reload()}
 async function toggle(s:Student){if(!supabase)return;const {error}=await supabase.from('students').update({active:!s.active}).eq('id',s.id);if(error)setMsg(error.message);else reload()}
 return <div className="card" style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,marginBottom:18,flexWrap:'wrap'}}><div><h2 style={{margin:0}}>Students</h2><p className="muted">Edit, activate/deactivate or safely delete student records.</p></div><div style={{position:'relative'}}><Search size={16} style={{position:'absolute',left:10,top:12}}/><input className="field" style={{paddingLeft:34,width:250}} placeholder="Search name, phone or ID…" value={q} onChange={e=>setQ(e.target.value)}/></div></div>{msg&&<div style={{background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10,marginBottom:14}}>{msg}</div>}<div style={{overflowX:'auto'}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}><thead><tr>{['Student ID','Name','Phone','Registered','Demos','Status','Actions'].map(h=><th key={h} style={{textAlign:'left',padding:10,borderBottom:'1px solid #E5E7EB',whiteSpace:'nowrap'}}>{h}</th>)}</tr></thead><tbody>{filtered.map(s=><tr key={s.id}><td style={{padding:10,fontWeight:800}}>{s.student_code}</td><td style={{padding:10}}>{s.name}</td><td style={{padding:10}}>{s.phone}</td><td style={{padding:10,whiteSpace:'nowrap'}}>{new Date(s.created_at).toLocaleDateString()}</td><td style={{padding:10}}>{bookings.filter(b=>b.student_id===s.id).length}</td><td style={{padding:10}}><button className="btn btn-ghost" style={{padding:'6px 9px',color:s.active?'#15803d':'#b33a1f'}} onClick={()=>toggle(s)}>{s.active?'Active':'Inactive'}</button></td><td style={{padding:10}}><ActionButtons onEdit={()=>openEdit(s)} onDelete={()=>remove(s)}/></td></tr>)}</tbody></table></div>{!filtered.length&&<div className="muted" style={{padding:25,textAlign:'center'}}>No students found.</div>}{editing&&<Modal title={`Edit Student — ${editing.student_code}`} onClose={()=>setEditing(null)}><div style={{display:'grid',gap:14,marginTop:20}}><Field label="Full name"><input className="field" value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Phone"><input className="field" value={phone} onChange={e=>setPhone(e.target.value)} inputMode="tel"/></Field><label style={{display:'flex',gap:8,alignItems:'center',fontWeight:700}}><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> Active student</label>{msg&&<div style={{background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{display:'flex',justifyContent:'flex-end',gap:8}}><button className="btn btn-ghost" onClick={()=>setEditing(null)}>Cancel</button><button className="btn btn-orange" disabled={busy||name.trim().length<2||api.normalizePhone(phone).length!==11} onClick={save}>{busy?'Saving…':'Save Changes'}</button></div></div></Modal>}</div>}

function CourseAdmin({courses,bookings,reload}:{courses:Course[];bookings:Booking[];reload:()=>void}){
 const [name,setName]=useState('');const [code,setCode]=useState('');const [busy,setBusy]=useState(false);const [editing,setEditing]=useState<Course|null>(null);const [modalOpen,setModalOpen]=useState(false);const [msg,setMsg]=useState('');
 function openAdd(){setEditing(null);setName('');setCode('');setMsg('');setModalOpen(true)}
 async function add(){if(!supabase)return;if(!name.trim()||!code.trim()){setMsg('Course name and course code are required.');return}setBusy(true);setMsg('');try{const {error}=await supabase.from('courses').insert({name:name.trim(),course_code:code.trim().toUpperCase(),active:true});if(error)throw error;setModalOpen(false);setName('');setCode('');await reload()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 function openEdit(c:Course){setEditing(c);setName(c.name);setCode(c.course_code);setMsg('');setModalOpen(true)}
 async function save(){if(!supabase||!editing)return;if(!name.trim()||!code.trim()){setMsg('Course name and course code are required.');return}setBusy(true);setMsg('');try{const {error}=await supabase.from('courses').update({name:name.trim(),course_code:code.trim().toUpperCase()}).eq('id',editing.id);if(error)throw error;setModalOpen(false);setEditing(null);await reload()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 async function toggle(c:Course){if(!supabase)return;const {error}=await supabase.from('courses').update({active:!c.active}).eq('id',c.id);if(error)setMsg(error.message);else reload()}
 async function remove(c:Course){if(!supabase)return;const has=bookings.some(b=>b.course_id===c.id);if(has){setMsg(`Cannot permanently delete ${c.name} because booking history exists. Deactivate the course instead.`);return}if(!confirm(`Delete course ${c.name} (${c.course_code})?`))return;const {error}=await supabase.from('courses').delete().eq('id',c.id);if(error)setMsg(error.message);else reload()}
 return <div className="card" style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'end',gap:15,flexWrap:'wrap'}}><div><h2 style={{marginBottom:5}}>Courses</h2><p className="muted">Add, edit, activate/deactivate or safely delete courses.</p></div><button className="btn btn-orange" type="button" onClick={openAdd}><Plus size={16}/> Add Course</button></div>{msg&&!modalOpen&&<div style={{marginTop:14,background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{overflowX:'auto',marginTop:22}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}><thead><tr>{['Course ID','Course','Code','Demos','Status','Actions'].map(h=><th key={h} style={{textAlign:'left',padding:10,borderBottom:'1px solid #E5E7EB',whiteSpace:'nowrap'}}>{h}</th>)}</tr></thead><tbody>{courses.map(c=><tr key={c.id}><td style={{padding:10,fontWeight:700}}>{c.course_code}</td><td style={{padding:10}}>{c.name}</td><td style={{padding:10}}>{c.course_code}</td><td style={{padding:10}}>{bookings.filter(b=>b.course_id===c.id).length}</td><td style={{padding:10}}><button className="btn btn-ghost" style={{padding:'6px 9px',color:c.active?'#15803d':'#b33a1f'}} onClick={()=>toggle(c)}>{c.active?'Active':'Inactive'}</button></td><td style={{padding:10}}><ActionButtons onEdit={()=>openEdit(c)} onDelete={()=>remove(c)}/></td></tr>)}</tbody></table></div>{!courses.length&&<div className="muted" style={{padding:25,textAlign:'center'}}>No courses found. Click “Add Course” to create one.</div>}{modalOpen&&<Modal title={editing?`Edit Course — ${editing.course_code}`:'Add Course'} onClose={()=>{setModalOpen(false);setEditing(null);setMsg('')}}><div style={{display:'grid',gap:14,marginTop:20}}><Field label="Course name"><input autoFocus className="field" placeholder="e.g. AI Development" value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Course code"><input className="field" placeholder="e.g. AI" value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/></Field>{msg&&<div style={{background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{display:'flex',justifyContent:'flex-end',gap:8}}><button type="button" className="btn btn-ghost" onClick={()=>{setModalOpen(false);setEditing(null);setMsg('')}}>Cancel</button><button type="button" className="btn btn-orange" disabled={busy} onClick={editing?save:add}>{busy?(editing?'Saving…':'Adding…'):(editing?'Save Changes':'Add Course')}</button></div></div></Modal>}</div>}

function BookingAdmin({bookings,courses,instructors,students,reload}:{bookings:Booking[];courses:Course[];instructors:Instructor[];students:Student[];reload:()=>void}){
 const [q,setQ]=useState('');const [status,setStatus]=useState('');const [editing,setEditing]=useState<Booking|null>(null);const [editStatus,setEditStatus]=useState<BookingStatus>('Confirmed');const [date,setDate]=useState('');const [start,setStart]=useState('');const [end,setEnd]=useState('');const [mode,setMode]=useState<Mode>('Online');const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');
 const filtered=bookings.filter(b=>{const hay=`${b.booking_code} ${b.student_code} ${b.student_name} ${b.student_phone} ${b.course_name} ${b.instructor_name}`.toLowerCase();return hay.includes(q.toLowerCase())&&(!status||b.status===status)});
 function openEdit(b:Booking){setEditing(b);setEditStatus(b.status);setDate(b.demo_date);setStart(b.start_time.slice(0,5));setEnd(b.end_time.slice(0,5));setMode(b.mode);setMsg('')}
 async function save(){if(!supabase||!editing)return;if(!date||!start||!end||start>=end){setMsg('Please enter a valid date and time.');return}setBusy(true);setMsg('');try{const {error}=await supabase.from('demo_bookings').update({status:editStatus,demo_date:date,start_time:start,end_time:end,mode}).eq('id',editing.id);if(error)throw error;setEditing(null);await reload()}catch(e:any){setMsg(e.message.includes('duplicate')?'That instructor time is already booked. Choose another time.':e.message)}finally{setBusy(false)}}
 async function remove(b:Booking){if(!supabase)return;if(!confirm(`Delete booking ${b.booking_code}? This will release its slot if it is confirmed.`))return;const {error}=await supabase.from('demo_bookings').delete().eq('id',b.id);if(error)setMsg(error.message);else reload()}
 async function setQuickStatus(b:Booking,s:BookingStatus){if(!supabase)return;const {error}=await supabase.from('demo_bookings').update({status:s}).eq('id',b.id);if(error)setMsg(error.message);else reload()}
 return <div className="card" style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',gap:12,marginBottom:18,flexWrap:'wrap'}}><div><h2 style={{margin:0}}>Demo Bookings</h2><p className="muted">Edit booking details, update status or delete a booking.</p></div><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><div style={{position:'relative'}}><Search size={16} style={{position:'absolute',left:10,top:12}}/><input className="field" style={{paddingLeft:34,width:230}} placeholder="Search booking…" value={q} onChange={e=>setQ(e.target.value)}/></div><select className="field" style={{width:150}} value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option>{['Confirmed','Completed','Cancelled','No Show'].map(x=><option key={x}>{x}</option>)}</select></div></div>{msg&&<div style={{background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10,marginBottom:14}}>{msg}</div>}<div style={{overflowX:'auto'}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}><thead><tr>{['Booking ID','Student','Course','Instructor','Mode','Date','Time','Status','Actions'].map(h=><th key={h} style={{textAlign:'left',padding:10,borderBottom:'1px solid #E5E7EB',whiteSpace:'nowrap'}}>{h}</th>)}</tr></thead><tbody>{filtered.map(b=><tr key={b.id}><td style={{padding:10,fontWeight:800}}>{b.booking_code}</td><td style={{padding:10}}><b>{b.student_name}</b><div className="muted" style={{fontSize:11}}>{b.student_code} · {b.student_phone}</div></td><td style={{padding:10}}>{b.course_name}</td><td style={{padding:10}}>{b.instructor_name}</td><td style={{padding:10}}>{b.mode}</td><td style={{padding:10}}>{b.demo_date}</td><td style={{padding:10}}>{b.start_time.slice(0,5)}–{b.end_time.slice(0,5)}</td><td style={{padding:10}}><select className="field" style={{padding:'7px 8px',width:125}} value={b.status} onChange={e=>setQuickStatus(b,e.target.value as BookingStatus)}>{['Confirmed','Completed','Cancelled','No Show'].map(x=><option key={x}>{x}</option>)}</select></td><td style={{padding:10}}><ActionButtons onEdit={()=>openEdit(b)} onDelete={()=>remove(b)}/></td></tr>)}</tbody></table></div>{!filtered.length&&<div className="muted" style={{padding:25,textAlign:'center'}}>No bookings found.</div>}{editing&&<Modal title={`Edit Booking — ${editing.booking_code}`} wide onClose={()=>setEditing(null)}><p className="muted" style={{marginTop:6}}>Student, course and instructor snapshots are preserved for historical reporting.</p><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginTop:18}}><Field label="Student"><input className="field" value={`${editing.student_name} (${editing.student_code})`} disabled/></Field><Field label="Course"><input className="field" value={editing.course_name} disabled/></Field><Field label="Instructor"><input className="field" value={editing.instructor_name} disabled/></Field><Field label="Mode"><select className="field" value={mode} onChange={e=>setMode(e.target.value as Mode)}><option>Online</option><option>Physical</option></select></Field><Field label="Date"><input className="field" type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Status"><select className="field" value={editStatus} onChange={e=>setEditStatus(e.target.value as BookingStatus)}>{['Confirmed','Completed','Cancelled','No Show'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Start time"><input className="field" type="time" value={start} onChange={e=>setStart(e.target.value)}/></Field><Field label="End time"><input className="field" type="time" value={end} onChange={e=>setEnd(e.target.value)}/></Field></div>{msg&&<div style={{marginTop:14,background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{display:'flex',justifyContent:'flex-end',gap:8,marginTop:22}}><button className="btn btn-ghost" onClick={()=>setEditing(null)}>Cancel</button><button className="btn btn-orange" disabled={busy} onClick={save}>{busy?'Saving…':'Save Changes'}</button></div></Modal>}</div>}

function InstructorAdmin({instructors,courses,bookings,reload}:{instructors:Instructor[];courses:Course[];bookings:Booking[];reload:()=>void}){
 const [editing,setEditing]=useState<Instructor|null>(null);const [modalOpen,setModalOpen]=useState(false);const [name,setName]=useState('');const [email,setEmail]=useState('');const [phone,setPhone]=useState('');const [active,setActive]=useState(true);const [assigned,setAssigned]=useState<string[]>([]);const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');
 function reset(){setEditing(null);setModalOpen(false);setName('');setEmail('');setPhone('');setActive(true);setAssigned([]);setMsg('')}
 function openAdd(){reset();setModalOpen(true)}
 function openEdit(i:Instructor){setEditing(i);setName(i.name);setEmail(i.email);setPhone(i.phone||'');setActive(i.active);setMsg('');setModalOpen(true);supabase!.from('instructor_courses').select('course_id').eq('instructor_id',i.id).then(({data})=>setAssigned((data||[]).map(x=>x.course_id)))}
 async function add(){if(!supabase)return;if(!name.trim()||!email.trim()){setMsg('Instructor name and email are required.');return}setBusy(true);setMsg('');try{const {data,error}=await supabase.from('instructors').insert({name:name.trim(),email:email.trim(),phone:phone.trim()||null,active:true}).select('id').single();if(error)throw error;if(assigned.length){const {error:e}=await supabase.from('instructor_courses').insert(assigned.map(course_id=>({instructor_id:data.id,course_id})));if(e)throw e}reset();await reload()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 async function save(){if(!editing||!supabase)return;if(!name.trim()||!email.trim()){setMsg('Instructor name and email are required.');return}setBusy(true);setMsg('');try{const {error}=await supabase.from('instructors').update({name:name.trim(),email:email.trim(),phone:phone.trim()||null,active}).eq('id',editing.id);if(error)throw error;await supabase.from('instructor_courses').delete().eq('instructor_id',editing.id);if(assigned.length){const {error:e}=await supabase.from('instructor_courses').insert(assigned.map(course_id=>({instructor_id:editing.id,course_id})));if(e)throw e}reset();await reload()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 async function remove(i:Instructor){if(!supabase)return;const has=bookingsForInstructor(i.id);if(has){setMsg(`Cannot permanently delete ${i.name} because historical bookings exist. Deactivate instead.`);return}if(!confirm(`Delete instructor ${i.name}?`))return;const {error}=await supabase.from('instructors').delete().eq('id',i.id);if(error)setMsg(error.message);else reload()}
 function bookingsForInstructor(id:string){return bookings.some(b=>b.instructor_id===id)}
 async function deactivate(i:Instructor){if(!supabase)return;const {error}=await supabase.from('instructors').update({active:!i.active}).eq('id',i.id);if(error)setMsg(error.message);else reload()}
 return <div className="card" style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',gap:15,alignItems:'center',flexWrap:'wrap'}}><div><h2 style={{margin:0}}>Instructors</h2><p className="muted">Add, edit profile, assign courses and manage active status.</p></div><button className="btn btn-orange" type="button" onClick={openAdd}><Plus size={16}/> Add Instructor</button></div>{msg&&!modalOpen&&<div style={{marginTop:14,background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{overflowX:'auto',marginTop:18}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}><thead><tr>{['ID','Name','Email','Assigned Courses','Status','Actions'].map(h=><th key={h} style={{textAlign:'left',padding:10,borderBottom:'1px solid #E5E7EB'}}>{h}</th>)}</tr></thead><tbody>{instructors.map(i=><tr key={i.id}><td style={{padding:10}}>{i.instructor_code}</td><td style={{padding:10,fontWeight:700}}>{i.name}</td><td style={{padding:10}}>{i.email}</td><td style={{padding:10}}><button className="btn btn-ghost" style={{padding:'7px 10px'}} onClick={()=>openEdit(i)}>Manage</button></td><td style={{padding:10}}><button className="btn btn-ghost" style={{padding:'7px 10px',color:i.active?'#15803d':'#b33a1f'}} onClick={()=>deactivate(i)}>{i.active?'Active':'Inactive'}</button></td><td style={{padding:10,display:'flex',gap:6}}><button className="btn btn-ghost" style={{padding:'7px 10px'}} onClick={()=>openEdit(i)}><Edit3 size={14}/> Edit</button><button className="btn btn-ghost" style={{padding:'7px 10px',color:'#b33a1f'}} onClick={()=>remove(i)}><Trash2 size={14}/> Delete</button></td></tr>)}</tbody></table></div>{!instructors.length&&<div className="muted" style={{padding:25,textAlign:'center'}}>No instructors found. Click “Add Instructor” to create one.</div>}{modalOpen&&<Modal title={editing?`Edit Instructor — ${editing.instructor_code}`:'Add Instructor'} wide onClose={reset}><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginTop:20}}><Field label="Name"><input autoFocus className="field" placeholder="Instructor full name" value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Email"><input className="field" type="email" placeholder="instructor@example.com" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Phone"><input className="field" placeholder="03XXXXXXXXX" value={phone} onChange={e=>setPhone(e.target.value)}/></Field><div></div></div><label className="label" style={{marginTop:18}}>Assigned Courses</label><div style={{display:'grid',gridTemplateColumns:'repeat(2,1fr)',gap:8,marginTop:8}}>{courses.map(c=><label key={c.id} className="btn btn-ghost" style={{display:'flex',gap:8,alignItems:'center',fontWeight:600}}><input type="checkbox" checked={assigned.includes(c.id)} onChange={e=>setAssigned(a=>e.target.checked?(a.includes(c.id)?a:[...a,c.id]):a.filter(x=>x!==c.id))}/>{c.name}</label>)}</div><label style={{display:'flex',alignItems:'center',gap:8,marginTop:18,fontWeight:700}}><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> Active instructor</label>{msg&&<div style={{marginTop:14,background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{display:'flex',justifyContent:'flex-end',gap:8,marginTop:24}}><button type="button" className="btn btn-ghost" onClick={reset}>Cancel</button><button type="button" className="btn btn-orange" disabled={busy} onClick={editing?save:add}>{busy?(editing?'Saving…':'Adding…'):(editing?'Save Changes':'Add Instructor')}</button></div></Modal>}</div>}

type ScheduleTiming={start_time:string;end_time:string;slot_duration_minutes:number};

function ScheduleAdmin({instructors,courses}:{instructors:Instructor[];courses:Course[]}){
 const [rows,setRows]=useState<Schedule[]>([]);
 const [editing,setEditing]=useState<Schedule|null>(null);
 const [modalOpen,setModalOpen]=useState(false);
 const [busy,setBusy]=useState(false);
 const [msg,setMsg]=useState('');
 const [filterInstructor,setFilterInstructor]=useState('');
 const dayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 const blank=():Schedule=>({id:'',instructor_id:instructors[0]?.id||'',course_id:courses[0]?.id||'',mode:'Online',day_of_week:1,start_time:'16:00',end_time:'19:00',slot_duration_minutes:60,active:true});
 const [form,setForm]=useState<Schedule>(blank());
 const [selectedModes,setSelectedModes]=useState<Mode[]>(['Online']);
 const [selectedDays,setSelectedDays]=useState<number[]>([1]);
 const [timings,setTimings]=useState<ScheduleTiming[]>([{start_time:'16:00',end_time:'19:00',slot_duration_minutes:60}]);

 async function load(){
  if(!supabase)return;
  const {data,error}=await supabase.from('instructor_schedules').select('*').order('day_of_week').order('start_time');
  if(error)setMsg(error.message);else setRows(data||[]);
 }
 useEffect(()=>{load()},[instructors.length,courses.length]);

 function edit(r:Schedule){
  setEditing(r);setForm({...r});setSelectedModes([r.mode]);setSelectedDays([Number(r.day_of_week)]);
  setTimings([{start_time:r.start_time.slice(0,5),end_time:r.end_time.slice(0,5),slot_duration_minutes:Number(r.slot_duration_minutes)}]);
  setModalOpen(true);setMsg('');
 }
 function add(){
  const f=blank();setEditing(null);setForm(f);setSelectedModes(['Online']);setSelectedDays([1]);setTimings([{start_time:'16:00',end_time:'19:00',slot_duration_minutes:60}]);setModalOpen(true);setMsg('');
 }
 function closeModal(){setEditing(null);setModalOpen(false);setForm(blank());setSelectedModes(['Online']);setSelectedDays([1]);setTimings([{start_time:'16:00',end_time:'19:00',slot_duration_minutes:60}]);setMsg('')}
 function toggleMode(mode:Mode){setSelectedModes(m=>m.includes(mode)?m.filter(x=>x!==mode):[...m,mode])}
 function toggleDay(day:number){setSelectedDays(d=>d.includes(day)?d.filter(x=>x!==day):[...d,day])}
 function addTiming(){
  setTimings(t=>{
   const last=t[t.length-1]||{start_time:'16:00',end_time:'19:00',slot_duration_minutes:60};
   const start=last.end_time||'19:00';
   const [h,m]=start.split(':').map(Number);const endH=Math.min(23,h+3);
   const end=`${String(endH).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
   return [...t,{start_time:start,end_time:end,slot_duration_minutes:last.slot_duration_minutes}];
  });
 }
 function updateTiming(index:number,key:keyof ScheduleTiming,value:string|number){setTimings(t=>t.map((x,i)=>i===index?{...x,[key]:value}:x))}
 function removeTiming(index:number){setTimings(t=>t.length===1?t:t.filter((_,i)=>i!==index))}
 async function save(){
  if(!supabase)return;
  setMsg('');
  if(!form.instructor_id||!form.course_id){setMsg('Please select an instructor and course.');return}
  if(!selectedModes.length){setMsg('Select at least one mode.');return}
  if(!selectedDays.length){setMsg('Select at least one day.');return}
  if(!timings.length){setMsg('Add at least one demo timing.');return}
  for(const t of timings){
   if(!t.start_time||!t.end_time||t.end_time<=t.start_time){setMsg('Every timing must have an end time later than its start time.');return}
   if(Number(t.slot_duration_minutes)<=0){setMsg('Slot duration must be greater than 0.');return}
  }
  const payloads=selectedModes.flatMap(mode=>selectedDays.flatMap(day=>timings.map(t=>({instructor_id:form.instructor_id,course_id:form.course_id,mode,day_of_week:Number(day),start_time:t.start_time,end_time:t.end_time,slot_duration_minutes:Number(t.slot_duration_minutes),active:form.active}))));
  setBusy(true);
  try{
   if(editing){
    const first=payloads[0];
    const {error:updateError}=await supabase.from('instructor_schedules').update(first).eq('id',editing.id);
    if(updateError)throw updateError;
    if(payloads.length>1){const {error:insertError}=await supabase.from('instructor_schedules').insert(payloads.slice(1));if(insertError)throw insertError;}
   }else{
    const {error}=await supabase.from('instructor_schedules').insert(payloads);if(error)throw error;
   }
   closeModal();await load();setMsg(editing?'Schedule updated successfully.':'Schedule(s) added successfully.');
  }catch(e:any){setMsg(e.message||'Unable to save schedule.')}
  finally{setBusy(false)}
 }
 async function remove(r:Schedule){if(!supabase||!confirm(`Delete this ${dayNames[r.day_of_week]} ${r.start_time.slice(0,5)}–${r.end_time.slice(0,5)} schedule?`))return;const {error}=await supabase.from('instructor_schedules').delete().eq('id',r.id);if(error)setMsg(error.message);else load()}
 async function toggle(r:Schedule){if(!supabase)return;const {error}=await supabase.from('instructor_schedules').update({active:!r.active}).eq('id',r.id);if(error)setMsg(error.message);else load()}
 const filtered=rows.filter(r=>!filterInstructor||r.instructor_id===filterInstructor);
 return <div className="card" style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',gap:15,alignItems:'center',flexWrap:'wrap'}}><div><h2 style={{margin:0}}>Instructor Schedules</h2><p className="muted">Create multiple demo timings across multiple days and modes in one go.</p></div><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><select className="field" style={{width:190}} value={filterInstructor} onChange={e=>setFilterInstructor(e.target.value)}><option value="">All instructors</option>{instructors.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select><button className="btn btn-orange" type="button" onClick={add}><Plus size={16}/> Add Schedule</button></div></div>{msg&&<div style={{marginTop:14,background:'#fff1ed',color:'#b33a1f',padding:12,borderRadius:10}}>{msg}</div>}<div style={{overflowX:'auto',marginTop:18}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}><thead><tr>{['Instructor','Course','Mode','Day','Start','End','Slot','Status','Actions'].map(h=><th key={h} style={{textAlign:'left',padding:10,borderBottom:'1px solid #E5E7EB',whiteSpace:'nowrap'}}>{h}</th>)}</tr></thead><tbody>{filtered.map(r=>{const i=instructors.find(x=>x.id===r.instructor_id);const c=courses.find(x=>x.id===r.course_id);return <tr key={r.id}><td style={{padding:10,fontWeight:700}}>{i?.name||'—'}</td><td style={{padding:10}}>{c?.name||'—'}</td><td style={{padding:10}}>{r.mode}</td><td style={{padding:10}}>{dayNames[r.day_of_week]}</td><td style={{padding:10}}>{r.start_time.slice(0,5)}</td><td style={{padding:10}}>{r.end_time.slice(0,5)}</td><td style={{padding:10}}>{r.slot_duration_minutes} min</td><td style={{padding:10}}><button className="btn btn-ghost" style={{padding:'6px 9px',color:r.active?'#15803d':'#b33a1f'}} onClick={()=>toggle(r)}>{r.active?'Active':'Inactive'}</button></td><td style={{padding:10,display:'flex',gap:6}}><button className="btn btn-ghost" style={{padding:'7px 10px'}} onClick={()=>edit(r)}><Edit3 size={14}/> Edit</button><button className="btn btn-ghost" style={{padding:'7px 10px',color:'#b33a1f'}} onClick={()=>remove(r)}><Trash2 size={14}/> Delete</button></td></tr>})}</tbody></table></div>{!filtered.length&&<div className="muted" style={{padding:25,textAlign:'center'}}>No schedules found. Click Add Schedule to create one.</div>}{modalOpen&&<ScheduleModal form={form} setForm={setForm} instructors={instructors} courses={courses} busy={busy} editing={editing} selectedModes={selectedModes} selectedDays={selectedDays} timings={timings} onToggleMode={toggleMode} onToggleDay={toggleDay} onAddTiming={addTiming} onUpdateTiming={updateTiming} onRemoveTiming={removeTiming} onClose={closeModal} onSave={save}/>}</div>
}

function ScheduleModal({form,setForm,instructors,courses,busy,editing,selectedModes,selectedDays,timings,onToggleMode,onToggleDay,onAddTiming,onUpdateTiming,onRemoveTiming,onClose,onSave}:{form:Schedule;setForm:React.Dispatch<React.SetStateAction<Schedule>>;instructors:Instructor[];courses:Course[];busy:boolean;editing:Schedule|null;selectedModes:Mode[];selectedDays:number[];timings:ScheduleTiming[];onToggleMode:(mode:Mode)=>void;onToggleDay:(day:number)=>void;onAddTiming:()=>void;onUpdateTiming:(index:number,key:keyof ScheduleTiming,value:string|number)=>void;onRemoveTiming:(index:number)=>void;onClose:()=>void;onSave:()=>void}){
 const dayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 const modeOptions:[Mode,string,string][]= [['Online','Online Demo','Students join remotely'],['Physical','Physical Demo','Students visit the institute']];
 return <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,.4)',display:'grid',placeItems:'center',padding:20,zIndex:100}}><div className="card" style={{width:'min(850px,100%)',maxHeight:'92vh',overflowY:'auto',padding:28}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:15}}><div><h2 style={{margin:0}}>{editing?'Edit Schedule':'Add Schedule'}</h2><p className="muted">Choose multiple modes, days and demo timings. The system creates the required schedule slots automatically.</p></div><button type="button" className="btn btn-ghost" onClick={onClose}><X size={18}/></button></div>
 <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginTop:20}}><div><label className="label">Instructor</label><select className="field" value={form.instructor_id} onChange={e=>setForm(f=>({...f,instructor_id:e.target.value}))}>{instructors.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></div><div><label className="label">Course</label><select className="field" value={form.course_id} onChange={e=>setForm(f=>({...f,course_id:e.target.value}))}>{courses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div></div>
 <div style={{marginTop:22}}><div className="label">Mode <span className="muted" style={{fontWeight:400}}>(select one or both)</span></div><div style={{display:'grid',gridTemplateColumns:'repeat(2,minmax(0,1fr))',gap:10,marginTop:8}}>{modeOptions.map(([value,title,desc])=>{const checked=selectedModes.includes(value);return <label key={value} style={{display:'flex',gap:11,alignItems:'flex-start',padding:14,border:`1px solid ${checked?brand.orange:'#E5E7EB'}`,borderRadius:12,background:checked?'#FFF7F0':'#fff',cursor:'pointer'}}><input type="checkbox" checked={checked} onChange={()=>onToggleMode(value)} style={{marginTop:3}}/><span><b>{title}</b><span className="muted" style={{display:'block',fontSize:12,marginTop:3}}>{desc}</span></span></label>})}</div></div>
 <div style={{marginTop:22}}><div className="label">Days <span className="muted" style={{fontWeight:400}}>(select all days you want)</span></div><div style={{display:'grid',gridTemplateColumns:'repeat(4,minmax(0,1fr))',gap:8,marginTop:8}}>{dayNames.map((day,index)=>{const checked=selectedDays.includes(index);return <label key={day} style={{display:'flex',alignItems:'center',gap:8,padding:'11px 12px',border:`1px solid ${checked?brand.orange:'#E5E7EB'}`,borderRadius:10,background:checked?'#FFF7F0':'#fff',cursor:'pointer',fontWeight:600}}><input type="checkbox" checked={checked} onChange={()=>onToggleDay(index)}/>{day}</label>})}</div></div>
 <div style={{marginTop:22}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:10}}><div><div className="label" style={{marginBottom:2}}>Demo Timings</div><div className="muted" style={{fontSize:12}}>Add as many separate demo windows as needed.</div></div><button type="button" className="btn btn-ghost" onClick={onAddTiming}><Plus size={15}/> Add Timing</button></div><div style={{display:'grid',gap:10,marginTop:10}}>{timings.map((t,index)=><div key={index} style={{border:'1px solid #E5E7EB',borderRadius:12,padding:14,background:'#FAFBFC'}}><div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr auto',gap:10,alignItems:'end'}}><div><label className="label">Start time</label><input className="field" type="time" value={t.start_time.slice(0,5)} onChange={e=>onUpdateTiming(index,'start_time',e.target.value)}/></div><div><label className="label">End time</label><input className="field" type="time" value={t.end_time.slice(0,5)} onChange={e=>onUpdateTiming(index,'end_time',e.target.value)}/></div><div><label className="label">Slot duration</label><select className="field" value={t.slot_duration_minutes} onChange={e=>onUpdateTiming(index,'slot_duration_minutes',Number(e.target.value))}><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option><option value="90">90 minutes</option><option value="120">120 minutes</option></select></div><button type="button" className="btn btn-ghost" disabled={timings.length===1} onClick={()=>onRemoveTiming(index)} title="Remove timing" style={{padding:'10px 11px',color:timings.length===1?'#9CA3AF':'#b33a1f'}}><Trash2 size={16}/></button></div><div className="muted" style={{fontSize:12,marginTop:8}}>This window will be repeated for every selected day and mode.</div></div>)}</div></div>
 <label style={{display:'flex',alignItems:'center',gap:8,marginTop:20,fontWeight:700}}><input type="checkbox" checked={form.active} onChange={e=>setForm(f=>({...f,active:e.target.checked}))}/> Active schedule</label>
 <div style={{display:'flex',justifyContent:'flex-end',gap:8,marginTop:24}}><button type="button" className="btn btn-ghost" onClick={onClose}>Cancel</button><button type="button" className="btn btn-orange" disabled={busy||!form.instructor_id||!form.course_id} onClick={onSave}>{busy?(editing?'Saving…':'Adding…'):(editing?'Save Changes':'Save Schedule')}</button></div>
 </div></div>
}

function Reports({students,courses,instructors,bookings}:{students:Student[];courses:Course[];instructors:Instructor[];bookings:Booking[]}){
 const [busy,setBusy]=useState(false);const [msg,setMsg]=useState('');
 const dateStr=new Date().toISOString().slice(0,10);
 const bookingRows=bookings.map(b=>({Booking_ID:b.booking_code,Student_ID:b.student_code,Name:b.student_name,Phone:b.student_phone,Course:b.course_name,Course_Code:b.course_code,Instructor:b.instructor_name,Instructor_Email:b.instructor_email,Mode:b.mode,Date:b.demo_date,Start:b.start_time,End:b.end_time,Status:b.status,Created_At:b.created_at}));
 const downloadCsv=()=>{const rows=bookingRows;const headers=Object.keys(rows[0]||{Booking_ID:'',Student_ID:'',Name:'',Phone:'',Course:'',Course_Code:'',Instructor:'',Instructor_Email:'',Mode:'',Date:'',Start:'',End:'',Status:'',Created_At:''});const esc=(v:any)=>`"${String(v??'').replaceAll('"','""')}"`;const csv=[headers.join(','),...rows.map(r=>headers.map(h=>esc((r as any)[h])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Aztec_IT_Report_${dateStr}.csv`;a.click();URL.revokeObjectURL(url)};
 async function exportExcel(){setBusy(true);setMsg('');try{let schedules:any[]=[];if(supabase){const {data,error}=await supabase.from('instructor_schedules').select('*').order('day_of_week').order('start_time');if(error)throw error;schedules=data||[]}const wb=new ExcelJS.Workbook();wb.creator='AZTEC IT INSTITUTE';wb.created=new Date();const title=(ws:any,text:string)=>{ws.mergeCells('A1:F1');const c=ws.getCell('A1');c.value=text;c.font={bold:true,size:18,color:{argb:'FFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'102A4A'}};c.alignment={vertical:'middle'};ws.getRow(1).height=30;ws.freezePanes={ySplit:3}};const add=(name:string,data:any[])=>{const ws=wb.addWorksheet(name);title(ws,`AZTEC IT INSTITUTE — ${name}`);if(!data.length){ws.getCell('A3').value='No records';return}const keys=Object.keys(data[0]);ws.addRow([]);ws.addRow(keys);const hr=ws.getRow(3);hr.font={bold:true,color:{argb:'FFFFFF'}};hr.fill={type:'pattern',pattern:'solid',fgColor:{argb:'F47B20'}};hr.alignment={wrapText:true};data.forEach(x=>ws.addRow(keys.map(k=>x[k])));if(keys.length<=26)ws.autoFilter=`A3:${String.fromCharCode(64+keys.length)}${ws.rowCount}`;keys.forEach((k,i)=>{const max=Math.max(k.length,...data.slice(0,200).map(x=>String(x[k]??'').length));ws.getColumn(i+1).width=Math.min(42,Math.max(12,max+2))})};const summary=wb.addWorksheet('Summary');title(summary,'AZTEC IT INSTITUTE — FULL REPORT');summary.getCell('A2').value=`Generated: ${new Date().toLocaleString()}`;[['Total Students',students.length],['Total Demo Bookings',bookings.length],['Confirmed',bookings.filter(x=>x.status==='Confirmed').length],['Completed',bookings.filter(x=>x.status==='Completed').length],['Cancelled',bookings.filter(x=>x.status==='Cancelled').length],['No Show',bookings.filter(x=>x.status==='No Show').length],['Active Courses',courses.filter(x=>x.active).length],['Active Instructors',instructors.filter(x=>x.active).length]].forEach(x=>summary.addRow(x));add('Students',students);add('Demo Bookings',bookingRows);add('Courses',courses);add('Instructors',instructors);add('Schedules',schedules);const buf=await wb.xlsx.writeBuffer();const blob=new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Aztec_IT_Full_Report_${dateStr}.xlsx`;a.click();URL.revokeObjectURL(url);setMsg('Excel report downloaded successfully.')}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}
 async function googleSheets(){setBusy(true);setMsg('');try{const {data:{session}}=await supabase!.auth.getSession();const res=await fetch('/.netlify/functions/export-report',{method:'POST',headers:{'content-type':'application/json',Authorization:`Bearer ${session?.access_token||''}`},body:JSON.stringify({format:'google-sheets'})});if(!res.ok)throw new Error(await res.text());const data=await res.json();setMsg(data.message||'Google Sheets export completed.')}catch(e:any){setMsg(window.location.hostname==='localhost'?'Google Sheets needs the Netlify function and Google credentials. Excel/CSV exports work locally.':e.message)}finally{setBusy(false)}}
 return <div className="card" style={{padding:28}}><h2>Export Center</h2><p className="muted">Download structured reports from your live Supabase data.</p><div style={{display:'flex',gap:10,flexWrap:'wrap',marginTop:20}}><button className="btn btn-orange" onClick={exportExcel} disabled={busy}><Download size={17}/> {busy?'Preparing…':'Export Excel'}</button><button className="btn btn-ghost" onClick={downloadCsv} disabled={busy}>Export CSV</button><button className="btn btn-ghost" onClick={googleSheets} disabled={busy}>Export to Google Sheets</button></div>{msg&&<div style={{marginTop:15,padding:12,borderRadius:10,background:'#F5F7FA'}}>{msg}</div>}</div>}

export function App(){const p=path();if(p==='/admin/login')return <AdminLogin/>;if(p.startsWith('/admin'))return <Admin/>;if(p==='/book')return <BookingFlow/>;return <Home/>}
